33	1	1	6f0e22d98609afe4731725f009ba9f6b	SELECT\n  date_trunc('day', m.measured_at)::date AS day,\n  s.name AS station,\n  SUM(m.precipitation_mm) AS precipitation_mm_total\nFROM weather_measurement m\nJOIN weather_station s ON s.id = m.station_id\nWHERE m.measured_at > now() - interval '7 days'\nGROUP BY day, station\nORDER BY day;	{"rows": [{"precipitation_mm_total": 0.4589036365382163, "station": "Station Center", "day": "2025-12-26"}, {"precipitation_mm_total": 1.5154995459876068, "station": "Station East", "day": "2025-12-26"}, {"precipitation_mm_total": 2.1476796351460425, "station": "Station North", "day": "2025-12-26"}, {"precipitation_mm_total": 0.4287372073407911, "station": "Station South", "day": "2025-12-26"}, {"precipitation_mm_total": 1.4773924867852606, "station": "Station West", "day": "2025-12-26"}], "columns": [{"type": "date", "friendly_name": "day", "name": "day"}, {"type": null, "friendly_name": "station", "name": "station"}, {"type": "float", "friendly_name": "precipitation_mm_total", "name": "precipitation_mm_total"}]}	0.006101846694946289	2025-12-26 05:11:58.344358+00
