118	1	1	bcfb535be898083d6eb7daf21078b7d3	WITH hours AS (\n  SELECT generate_series(\n    date_trunc('hour', now() AT TIME ZONE 'UTC') - interval '47 hours',\n    date_trunc('hour', now() AT TIME ZONE 'UTC'),\n    interval '1 hour'\n  ) AS hour_ts\n),\nstation_hour AS (\n  SELECT\n    h.hour_ts,\n    s.id AS station_id,\n    AVG(m.wind_speed_ms) AS station_avg\n  FROM hours h\n  CROSS JOIN weather_station s\n  LEFT JOIN weather_measurement m\n    ON m.station_id = s.id\n   AND date_trunc('hour', m.measured_at AT TIME ZONE 'UTC') = h.hour_ts\n  GROUP BY h.hour_ts, s.id\n)\nSELECT\n  sh.hour_ts AS measured_at,\n  AVG(sh.station_avg) AS wind_speed_ms\nFROM station_hour sh\nGROUP BY sh.hour_ts\nORDER BY sh.hour_ts;	{"rows": [{"wind_speed_ms": 2.8877973614369106, "measured_at": "2025-12-25T13:00:00"}, {"wind_speed_ms": 3.599764475196294, "measured_at": "2025-12-25T14:00:00"}, {"wind_speed_ms": 3.797082742929824, "measured_at": "2025-12-25T15:00:00"}, {"wind_speed_ms": 4.887276053759779, "measured_at": "2025-12-25T16:00:00"}, {"wind_speed_ms": 4.258164196036413, "measured_at": "2025-12-25T17:00:00"}, {"wind_speed_ms": 4.653568856477612, "measured_at": "2025-12-25T18:00:00"}, {"wind_speed_ms": 4.746254762031648, "measured_at": "2025-12-25T19:00:00"}, {"wind_speed_ms": 5.076859215187226, "measured_at": "2025-12-25T20:00:00"}, {"wind_speed_ms": 3.6828101643420923, "measured_at": "2025-12-25T21:00:00"}, {"wind_speed_ms": 4.489405842445433, "measured_at": "2025-12-25T22:00:00"}, {"wind_speed_ms": 4.893498751554838, "measured_at": "2025-12-25T23:00:00"}, {"wind_speed_ms": 6.014200611084145, "measured_at": "2025-12-26T00:00:00"}, {"wind_speed_ms": 4.571968094446746, "measured_at": "2025-12-26T01:00:00"}, {"wind_speed_ms": 5.529854956717522, "measured_at": "2025-12-26T02:00:00"}, {"wind_speed_ms": 5.617088431335873, "measured_at": "2025-12-26T03:00:00"}, {"wind_speed_ms": 5.07518125531732, "measured_at": "2025-12-26T04:00:00"}, {"wind_speed_ms": 4.784514365634713, "measured_at": "