128	1	1	bcfb535be898083d6eb7daf21078b7d3	WITH hours AS (\n  SELECT generate_series(\n    date_trunc('hour', now() AT TIME ZONE 'UTC') - interval '47 hours',\n    date_trunc('hour', now() AT TIME ZONE 'UTC'),\n    interval '1 hour'\n  ) AS hour_ts\n),\nstation_hour AS (\n  SELECT\n    h.hour_ts,\n    s.id AS station_id,\n    AVG(m.wind_speed_ms) AS station_avg\n  FROM hours h\n  CROSS JOIN weather_station s\n  LEFT JOIN weather_measurement m\n    ON m.station_id = s.id\n   AND date_trunc('hour', m.measured_at AT TIME ZONE 'UTC') = h.hour_ts\n  GROUP BY h.hour_ts, s.id\n)\nSELECT\n  sh.hour_ts AS measured_at,\n  AVG(sh.station_avg) AS wind_speed_ms\nFROM station_hour sh\nGROUP BY sh.hour_ts\nORDER BY sh.hour_ts;	{"rows": [{"wind_speed_ms": 4.798485827165498, "measured_at": "2025-12-25T13:00:00"}, {"wind_speed_ms": 4.4209405995458955, "measured_at": "2025-12-25T14:00:00"}, {"wind_speed_ms": 4.724249745535388, "measured_at": "2025-12-25T15:00:00"}, {"wind_speed_ms": 4.893535440305046, "measured_at": "2025-12-25T16:00:00"}, {"wind_speed_ms": 4.811037174723493, "measured_at": "2025-12-25T17:00:00"}, {"wind_speed_ms": 4.850429244467008, "measured_at": "2025-12-25T18:00:00"}, {"wind_speed_ms": 5.647642145567408, "measured_at": "2025-12-25T19:00:00"}, {"wind_speed_ms": 5.604783946467718, "measured_at": "2025-12-25T20:00:00"}, {"wind_speed_ms": 3.9197365054519855, "measured_at": "2025-12-25T21:00:00"}, {"wind_speed_ms": 4.818928610612899, "measured_at": "2025-12-25T22:00:00"}, {"wind_speed_ms": 5.233618536945363, "measured_at": "2025-12-25T23:00:00"}, {"wind_speed_ms": 6.249737264307226, "measured_at": "2025-12-26T00:00:00"}, {"wind_speed_ms": 4.55732394649629, "measured_at": "2025-12-26T01:00:00"}, {"wind_speed_ms": 4.787974144419058, "measured_at": "2025-12-26T02:00:00"}, {"wind_speed_ms": 5.508228760739259, "measured_at": "2025-12-26T03:00:00"}, {"wind_speed_ms": 5.100813377320364, "measured_at": "2025-12-26T04:00:00"}, {"wind_speed_ms": 4.235320035089647, "measured_at": "