129	1	1	76137ef460fc40a20c4b6f41a9460e3f	WITH rng AS (\n  SELECT date_trunc('month', now()) - interval '1 month' AS start_ts,\n         date_trunc('month', now())                         AS end_ts\n)\nSELECT\n  s.id   AS station_id,\n  s.name AS station,\n  AVG(m.temperature_c)    AS avg_temperature_c,\n  AVG(m.humidity_pct)     AS avg_humidity_pct,\n  AVG(m.pressure_hpa)     AS avg_pressure_hpa,\n  AVG(m.wind_speed_ms)    AS avg_wind_speed_ms,\n  CASE\n    WHEN degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg))))) < 0\n    THEN degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg))))) + 360\n    ELSE degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg)))))\n  END                     AS avg_wind_dir_deg,\n  AVG(m.precipitation_mm) AS avg_precipitation_mm\nFROM weather_measurement m\nJOIN weather_station s ON s.id = m.station_id\nJOIN rng r\n  ON m.measured_at >= r.start_ts\n AND m.measured_at <  r.end_ts\nGROUP BY s.id, s.name\nORDER BY s.name;	{"rows": [{"avg_pressure_hpa": 1013.1957024056534, "avg_humidity_pct": 69.35968285043054, "avg_temperature_c": 2.000660901011494, "station_id": 1, "station": "Station Center", "avg_precipitation_mm": 0.14560148292400255, "avg_wind_speed_ms": 5.029151240873487, "avg_wind_dir_deg": 147.2609416812639}, {"avg_pressure_hpa": 1012.8901320482007, "avg_humidity_pct": 70.75694553617707, "avg_temperature_c": 4.996381782887344, "station_id": 4, "station": "Station East", "avg_precipitation_mm": 0.14117363905560834, "avg_wind_speed_ms": 5.06375706341045, "avg_wind_dir_deg": 97.08729759909787}, {"avg_pressure_hpa": 1012.6729657790344, "avg_humidity_pct": 70.67907084032176, "avg_temperature_c": -5.084331608990266, "station_id": 2, "station": "Station North", "avg_precipitation_mm": 0.14118573727659925, "avg_wind_speed_ms": 5.037326838057674, "avg_wind_dir_deg": 293.32146612464464}, {"avg_pressure_hpa": 1012.8060931167512, "avg_humidity_pct": 69.8793034316