135	1	1	28281abe7f3a762ec93c2a21e298074f	WITH days AS (\n  SELECT generate_series(\n    date_trunc('day', now() AT TIME ZONE 'UTC') - interval '29 days',\n    date_trunc('day', now() AT TIME ZONE 'UTC'),\n    interval '1 day'\n  ) AS day_ts\n)\nSELECT\n  d.day_ts AS measured_date,\n  s.name   AS station,\n  AVG(m.temperature_c) AS temperature_c\nFROM days d\nCROSS JOIN weather_station s\nLEFT JOIN weather_measurement m\n  ON m.station_id = s.id\n AND date_trunc('day', m.measured_at AT TIME ZONE 'UTC') = d.day_ts\nGROUP BY d.day_ts, s.name\nORDER BY d.day_ts, s.name;	{"rows": [{"temperature_c": 2.029460984580408, "measured_date": "2025-11-28T00:00:00", "station": "Station Center"}, {"temperature_c": 4.658084824145965, "measured_date": "2025-11-28T00:00:00", "station": "Station East"}, {"temperature_c": -4.96304547313679, "measured_date": "2025-11-28T00:00:00", "station": "Station North"}, {"temperature_c": 7.751844959325432, "measured_date": "2025-11-28T00:00:00", "station": "Station South"}, {"temperature_c": 7.326009050468599, "measured_date": "2025-11-28T00:00:00", "station": "Station West"}, {"temperature_c": 2.3626291069736607, "measured_date": "2025-11-29T00:00:00", "station": "Station Center"}, {"temperature_c": 4.9227754836796755, "measured_date": "2025-11-29T00:00:00", "station": "Station East"}, {"temperature_c": -4.752367122568189, "measured_date": "2025-11-29T00:00:00", "station": "Station North"}, {"temperature_c": 7.806183666028308, "measured_date": "2025-11-29T00:00:00", "station": "Station South"}, {"temperature_c": 5.8812454506614245, "measured_date": "2025-11-29T00:00:00", "station": "Station West"}, {"temperature_c": 1.8720726845001439, "measured_date": "2025-11-30T00:00:00", "station": "Station Center"}, {"temperature_c": 4.911580324452326, "measured_date": "2025-11-30T00:00:00", "station": "Station East"}, {"temperature_c": -4.854690381792491, "measured_date": "2025-11-30T00:00:00", "station": "Station North"}, {"temperature_c": 8.11507709796107,