144	1	1	28281abe7f3a762ec93c2a21e298074f	WITH days AS (\n  SELECT generate_series(\n    date_trunc('day', now() AT TIME ZONE 'UTC') - interval '29 days',\n    date_trunc('day', now() AT TIME ZONE 'UTC'),\n    interval '1 day'\n  ) AS day_ts\n)\nSELECT\n  d.day_ts AS measured_date,\n  s.name   AS station,\n  AVG(m.temperature_c) AS temperature_c\nFROM days d\nCROSS JOIN weather_station s\nLEFT JOIN weather_measurement m\n  ON m.station_id = s.id\n AND date_trunc('day', m.measured_at AT TIME ZONE 'UTC') = d.day_ts\nGROUP BY d.day_ts, s.name\nORDER BY d.day_ts, s.name;	{"rows": [{"temperature_c": 1.6661194441778735, "measured_date": "2025-11-28T00:00:00", "station": "Station Center"}, {"temperature_c": 4.8119310027900974, "measured_date": "2025-11-28T00:00:00", "station": "Station East"}, {"temperature_c": -4.769033796190143, "measured_date": "2025-11-28T00:00:00", "station": "Station North"}, {"temperature_c": 8.175981768736202, "measured_date": "2025-11-28T00:00:00", "station": "Station South"}, {"temperature_c": 6.342997876505337, "measured_date": "2025-11-28T00:00:00", "station": "Station West"}, {"temperature_c": 1.789081082760567, "measured_date": "2025-11-29T00:00:00", "station": "Station Center"}, {"temperature_c": 5.284442430864536, "measured_date": "2025-11-29T00:00:00", "station": "Station East"}, {"temperature_c": -4.787873545433217, "measured_date": "2025-11-29T00:00:00", "station": "Station North"}, {"temperature_c": 7.8735750848905655, "measured_date": "2025-11-29T00:00:00", "station": "Station South"}, {"temperature_c": 6.822998127468363, "measured_date": "2025-11-29T00:00:00", "station": "Station West"}, {"temperature_c": 1.7807680652980082, "measured_date": "2025-11-30T00:00:00", "station": "Station Center"}, {"temperature_c": 5.1638428128695635, "measured_date": "2025-11-30T00:00:00", "station": "Station East"}, {"temperature_c": -5.373420869549513, "measured_date": "2025-11-30T00:00:00", "station": "Station North"}, {"temperature_c": 8.3551115295398