145	1	1	76137ef460fc40a20c4b6f41a9460e3f	WITH rng AS (\n  SELECT date_trunc('month', now()) - interval '1 month' AS start_ts,\n         date_trunc('month', now())                         AS end_ts\n)\nSELECT\n  s.id   AS station_id,\n  s.name AS station,\n  AVG(m.temperature_c)    AS avg_temperature_c,\n  AVG(m.humidity_pct)     AS avg_humidity_pct,\n  AVG(m.pressure_hpa)     AS avg_pressure_hpa,\n  AVG(m.wind_speed_ms)    AS avg_wind_speed_ms,\n  CASE\n    WHEN degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg))))) < 0\n    THEN degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg))))) + 360\n    ELSE degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg)))))\n  END                     AS avg_wind_dir_deg,\n  AVG(m.precipitation_mm) AS avg_precipitation_mm\nFROM weather_measurement m\nJOIN weather_station s ON s.id = m.station_id\nJOIN rng r\n  ON m.measured_at >= r.start_ts\n AND m.measured_at <  r.end_ts\nGROUP BY s.id, s.name\nORDER BY s.name;	{"rows": [{"avg_pressure_hpa": 1012.874605973354, "avg_humidity_pct": 70.36006686718238, "avg_temperature_c": 1.9978032315290102, "station_id": 1, "station": "Station Center", "avg_precipitation_mm": 0.14998010084586427, "avg_wind_speed_ms": 5.494551756334764, "avg_wind_dir_deg": 148.2285744257334}, {"avg_pressure_hpa": 1013.2406861716934, "avg_humidity_pct": 70.1139513968673, "avg_temperature_c": 4.928649687327776, "station_id": 4, "station": "Station East", "avg_precipitation_mm": 0.14912051435768636, "avg_wind_speed_ms": 5.389691016356007, "avg_wind_dir_deg": 285.68560006646874}, {"avg_pressure_hpa": 1012.8712679019377, "avg_humidity_pct": 70.03069666619268, "avg_temperature_c": -5.106541088597875, "station_id": 2, "station": "Station North", "avg_precipitation_mm": 0.1312086342549451, "avg_wind_speed_ms": 5.318375710997476, "avg_wind_dir_deg": 209.30452356965625}, {"avg_pressure_hpa": 1013.4338225197831, "avg_humidity_pct": 70.3166391045