189	1	1	76137ef460fc40a20c4b6f41a9460e3f	WITH rng AS (\n  SELECT date_trunc('month', now()) - interval '1 month' AS start_ts,\n         date_trunc('month', now())                         AS end_ts\n)\nSELECT\n  s.id   AS station_id,\n  s.name AS station,\n  AVG(m.temperature_c)    AS avg_temperature_c,\n  AVG(m.humidity_pct)     AS avg_humidity_pct,\n  AVG(m.pressure_hpa)     AS avg_pressure_hpa,\n  AVG(m.wind_speed_ms)    AS avg_wind_speed_ms,\n  CASE\n    WHEN degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg))))) < 0\n    THEN degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg))))) + 360\n    ELSE degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg)))))\n  END                     AS avg_wind_dir_deg,\n  AVG(m.precipitation_mm) AS avg_precipitation_mm\nFROM weather_measurement m\nJOIN weather_station s ON s.id = m.station_id\nJOIN rng r\n  ON m.measured_at >= r.start_ts\n AND m.measured_at <  r.end_ts\nGROUP BY s.id, s.name\nORDER BY s.name;	{"rows": [{"avg_pressure_hpa": 1012.6229576481078, "avg_humidity_pct": 70.65005317326651, "avg_temperature_c": 1.9769975082523334, "station_id": 1, "station": "Station Center", "avg_precipitation_mm": 0.16918931051396055, "avg_wind_speed_ms": 5.225946313754585, "avg_wind_dir_deg": 6.166994517988139}, {"avg_pressure_hpa": 1013.165289666857, "avg_humidity_pct": 69.81156279397918, "avg_temperature_c": 4.843348984736388, "station_id": 4, "station": "Station East", "avg_precipitation_mm": 0.14904291853967983, "avg_wind_speed_ms": 5.334996968270882, "avg_wind_dir_deg": 49.937406725217244}, {"avg_pressure_hpa": 1012.7760463598502, "avg_humidity_pct": 69.30690480494586, "avg_temperature_c": -4.908791683167716, "station_id": 2, "station": "Station North", "avg_precipitation_mm": 0.14534098599113401, "avg_wind_speed_ms": 5.5096996607653885, "avg_wind_dir_deg": 243.83960512805513}, {"avg_pressure_hpa": 1013.6163891359937, "avg_humidity_pct": 70.4644343