155	1	1	bcfb535be898083d6eb7daf21078b7d3	WITH hours AS (\n  SELECT generate_series(\n    date_trunc('hour', now() AT TIME ZONE 'UTC') - interval '47 hours',\n    date_trunc('hour', now() AT TIME ZONE 'UTC'),\n    interval '1 hour'\n  ) AS hour_ts\n),\nstation_hour AS (\n  SELECT\n    h.hour_ts,\n    s.id AS station_id,\n    AVG(m.wind_speed_ms) AS station_avg\n  FROM hours h\n  CROSS JOIN weather_station s\n  LEFT JOIN weather_measurement m\n    ON m.station_id = s.id\n   AND date_trunc('hour', m.measured_at AT TIME ZONE 'UTC') = h.hour_ts\n  GROUP BY h.hour_ts, s.id\n)\nSELECT\n  sh.hour_ts AS measured_at,\n  AVG(sh.station_avg) AS wind_speed_ms\nFROM station_hour sh\nGROUP BY sh.hour_ts\nORDER BY sh.hour_ts;	{"rows": [{"wind_speed_ms": 9.496522078806873, "measured_at": "2025-12-25T13:00:00"}, {"wind_speed_ms": 6.121961357350217, "measured_at": "2025-12-25T14:00:00"}, {"wind_speed_ms": 7.648888801959215, "measured_at": "2025-12-25T15:00:00"}, {"wind_speed_ms": 7.412101471572187, "measured_at": "2025-12-25T16:00:00"}, {"wind_speed_ms": 5.8397657651628965, "measured_at": "2025-12-25T17:00:00"}, {"wind_speed_ms": 5.0718937978000795, "measured_at": "2025-12-25T18:00:00"}, {"wind_speed_ms": 6.363418484083817, "measured_at": "2025-12-25T19:00:00"}, {"wind_speed_ms": 6.399665081832323, "measured_at": "2025-12-25T20:00:00"}, {"wind_speed_ms": 2.9064758475485895, "measured_at": "2025-12-25T21:00:00"}, {"wind_speed_ms": 2.5871993802457434, "measured_at": "2025-12-25T22:00:00"}, {"wind_speed_ms": 5.78178210778712, "measured_at": "2025-12-25T23:00:00"}, {"wind_speed_ms": 6.0719403189111505, "measured_at": "2025-12-26T00:00:00"}, {"wind_speed_ms": 6.595062741068912, "measured_at": "2025-12-26T01:00:00"}, {"wind_speed_ms": 4.513859838728348, "measured_at": "2025-12-26T02:00:00"}, {"wind_speed_ms": 2.7168101756419945, "measured_at": "2025-12-26T03:00:00"}, {"wind_speed_ms": 7.005116084310226, "measured_at": "2025-12-26T04:00:00"}, {"wind_speed_ms": 6.205468372585018, "measured_at