156	1	1	6f500752a38e9a9b8c9c7068472481b3	WITH rng AS (\n  SELECT date_trunc('month', now()) - interval '1 month' AS start_ts,\n         date_trunc('month', now())                         AS end_ts\n)\nSELECT\n  m.condition AS condition,\n  COUNT(*)    AS count\nFROM weather_measurement m\nJOIN rng r\n  ON m.measured_at >= r.start_ts\n AND m.measured_at <  r.end_ts\nGROUP BY m.condition\nORDER BY count DESC;	{"rows": [{"count": 2452, "condition": "clear"}, {"count": 995, "condition": "windy"}, {"count": 153, "condition": "drizzle"}], "columns": [{"type": null, "friendly_name": "condition", "name": "condition"}, {"type": "integer", "friendly_name": "count", "name": "count"}]}	0.019764184951782227	2025-12-27 12:49:10.47694+00
157	1	1	76137ef460fc40a20c4b6f41a9460e3f	WITH rng AS (\n  SELECT date_trunc('month', now()) - interval '1 month' AS start_ts,\n         date_trunc('month', now())                         AS end_ts\n)\nSELECT\n  s.id   AS station_id,\n  s.name AS station,\n  AVG(m.temperature_c)    AS avg_temperature_c,\n  AVG(m.humidity_pct)     AS avg_humidity_pct,\n  AVG(m.pressure_hpa)     AS avg_pressure_hpa,\n  AVG(m.wind_speed_ms)    AS avg_wind_speed_ms,\n  CASE\n    WHEN degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg))))) < 0\n    THEN degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg))))) + 360\n    ELSE degrees(atan2(AVG(sin(radians(m.wind_dir_deg))), AVG(cos(radians(m.wind_dir_deg)))))\n  END                     AS avg_wind_dir_deg,\n  AVG(m.precipitation_mm) AS avg_precipitation_mm\nFROM weather_measurement m\nJOIN weather_station s ON s.id = m.station_id\nJOIN rng r\n  ON m.measured_at >= r.start_ts\n AND m.measured_at <  r.end_ts\nGROUP BY s.id, s.name\nORDER BY s.name;	{"rows": [{"avg_pressure_hpa": 1012.6229576481081, "avg_humidity_pct": 70.65005317326651, "avg_temperature_c": 1.9769975082523357, "station_id": 1, "station": "Station Center", "avg_precipitation_mm": 0.1691893105139605, "avg_wind_speed_ms": 5.225946313754589, "avg_wind_dir_deg": 6.166994517988167}, {"avg_pressure_hpa": 1013.1652896668572, "avg_humidity_pct": 69.81156279397906, "avg_temperature_c": 4.843348984736386, "station_id": 4, "station": "Station East", "avg_precipitation_mm": 0.14904291853967971, "avg_wind_speed_ms": 5.334996968270887, "avg_wind_dir_deg": 49.937406725217244}, {"avg_pressure_hpa": 1012.7760463598498, "avg_humidity_pct": 69.30690480494579, "avg_temperature_c": -4.908791683167716, "station_id": 2, "station": "Station North", "avg_precipitation_mm": 0.14534098599113413, "avg_wind_speed_ms": 5.50969966076539, "avg_wind_dir_deg": 243.83960512805518}, {"avg_pressure_hpa": 1013.6163891359937, "avg_humidity_pct": 70.464434302