165	1	1	28281abe7f3a762ec93c2a21e298074f	WITH days AS (\n  SELECT generate_series(\n    date_trunc('day', now() AT TIME ZONE 'UTC') - interval '29 days',\n    date_trunc('day', now() AT TIME ZONE 'UTC'),\n    interval '1 day'\n  ) AS day_ts\n)\nSELECT\n  d.day_ts AS measured_date,\n  s.name   AS station,\n  AVG(m.temperature_c) AS temperature_c\nFROM days d\nCROSS JOIN weather_station s\nLEFT JOIN weather_measurement m\n  ON m.station_id = s.id\n AND date_trunc('day', m.measured_at AT TIME ZONE 'UTC') = d.day_ts\nGROUP BY d.day_ts, s.name\nORDER BY d.day_ts, s.name;	{"rows": [{"temperature_c": 1.4237946385465037, "measured_date": "2025-11-28T00:00:00", "station": "Station Center"}, {"temperature_c": 5.087530411103128, "measured_date": "2025-11-28T00:00:00", "station": "Station East"}, {"temperature_c": -5.018681683724904, "measured_date": "2025-11-28T00:00:00", "station": "Station North"}, {"temperature_c": 7.770138358921273, "measured_date": "2025-11-28T00:00:00", "station": "Station South"}, {"temperature_c": 6.394419381214764, "measured_date": "2025-11-28T00:00:00", "station": "Station West"}, {"temperature_c": 1.814207571208713, "measured_date": "2025-11-29T00:00:00", "station": "Station Center"}, {"temperature_c": 4.654055448140992, "measured_date": "2025-11-29T00:00:00", "station": "Station East"}, {"temperature_c": -5.360215531908946, "measured_date": "2025-11-29T00:00:00", "station": "Station North"}, {"temperature_c": 8.075323574788943, "measured_date": "2025-11-29T00:00:00", "station": "Station South"}, {"temperature_c": 6.460659178716867, "measured_date": "2025-11-29T00:00:00", "station": "Station West"}, {"temperature_c": 1.7926290923331718, "measured_date": "2025-11-30T00:00:00", "station": "Station Center"}, {"temperature_c": 5.259603513508494, "measured_date": "2025-11-30T00:00:00", "station": "Station East"}, {"temperature_c": -5.210932236604807, "measured_date": "2025-11-30T00:00:00", "station": "Station North"}, {"temperature_c": 8.197059720989046,