166	1	1	8cba30e6b7d1f4bc5be7dc6ffc258f52	WITH hours AS (\n  SELECT generate_series(\n    date_trunc('hour', now() AT TIME ZONE 'UTC') - interval '47 hours',\n    date_trunc('hour', now() AT TIME ZONE 'UTC'),\n    interval '1 hour'\n  ) AS hour_ts\n)\nSELECT\n  h.hour_ts AS measured_at,\n  s.name AS station,\n  AVG(m.temperature_c) AS temperature_c\nFROM hours h\nCROSS JOIN weather_station s\nLEFT JOIN weather_measurement m\n  ON m.station_id = s.id\n AND date_trunc('hour', m.measured_at AT TIME ZONE 'UTC') = h.hour_ts\nGROUP BY h.hour_ts, s.name\nORDER BY h.hour_ts, s.name;	{"rows": [{"temperature_c": 1.8810305738471478, "station": "Station Center", "measured_at": "2025-12-25T13:00:00"}, {"temperature_c": 5.046531479118339, "station": "Station East", "measured_at": "2025-12-25T13:00:00"}, {"temperature_c": -8.465026403826714, "station": "Station North", "measured_at": "2025-12-25T13:00:00"}, {"temperature_c": 4.482961572717738, "station": "Station South", "measured_at": "2025-12-25T13:00:00"}, {"temperature_c": 6.991778602790251, "station": "Station West", "measured_at": "2025-12-25T13:00:00"}, {"temperature_c": -2.4698476120178814, "station": "Station Center", "measured_at": "2025-12-25T14:00:00"}, {"temperature_c": 3.213686431341641, "station": "Station East", "measured_at": "2025-12-25T14:00:00"}, {"temperature_c": -8.92948878730055, "station": "Station North", "measured_at": "2025-12-25T14:00:00"}, {"temperature_c": 5.454611851547986, "station": "Station South", "measured_at": "2025-12-25T14:00:00"}, {"temperature_c": 2.765975435736394, "station": "Station West", "measured_at": "2025-12-25T14:00:00"}, {"temperature_c": 0.5327150347619596, "station": "Station Center", "measured_at": "2025-12-25T15:00:00"}, {"temperature_c": 3.004499230232893, "station": "Station East", "measured_at": "2025-12-25T15:00:00"}, {"temperature_c": -7.262762940108102, "station": "Station North", "measured_at": "2025-12-25T15:00:00"}, {"temperature_c": 2.919077978828239, "station": "Stat