173	1	1	f79098c11b55e9b6aef2a19967a56948	WITH seconds AS (\n  SELECT generate_series(\n    date_trunc('second', now() AT TIME ZONE 'UTC') - interval '360 seconds',\n    date_trunc('second', now() AT TIME ZONE 'UTC'),\n    interval '1 second'\n  ) AS second_ts\n)\nSELECT\n  s.second_ts AS measured_at,\n  ws.name     AS station,\n  AVG(m.temperature_c) AS temperature_c\nFROM seconds s\nCROSS JOIN weather_station ws\nLEFT JOIN weather_measurement m\n  ON m.station_id = ws.id\n AND date_trunc('second', m.measured_at AT TIME ZONE 'UTC') = s.second_ts\nGROUP BY s.second_ts, ws.name\nORDER BY s.second_ts, ws.name;	{"rows": [{"temperature_c": 0.6510720482915531, "station": "Station Center", "measured_at": "2025-12-27T12:50:05"}, {"temperature_c": 1.6422373591934862, "station": "Station East", "measured_at": "2025-12-27T12:50:05"}, {"temperature_c": -5.978195553649283, "station": "Station North", "measured_at": "2025-12-27T12:50:05"}, {"temperature_c": 8.676545947290492, "station": "Station South", "measured_at": "2025-12-27T12:50:05"}, {"temperature_c": 6.510995964943747, "station": "Station West", "measured_at": "2025-12-27T12:50:05"}, {"temperature_c": 2.1704356459052456, "station": "Station Center", "measured_at": "2025-12-27T12:50:06"}, {"temperature_c": 4.047395872902701, "station": "Station East", "measured_at": "2025-12-27T12:50:06"}, {"temperature_c": -7.567502178539408, "station": "Station North", "measured_at": "2025-12-27T12:50:06"}, {"temperature_c": 5.938406769850823, "station": "Station South", "measured_at": "2025-12-27T12:50:06"}, {"temperature_c": 6.296670953591832, "station": "Station West", "measured_at": "2025-12-27T12:50:06"}, {"temperature_c": -1.4375144147771444, "station": "Station Center", "measured_at": "2025-12-27T12:50:07"}, {"temperature_c": 5.661468988428639, "station": "Station East", "measured_at": "2025-12-27T12:50:07"}, {"temperature_c": -5.5542247186509766, "station": "Station North", "measured_at": "2025-12-27T12:50:07"}, {"temperature_c"