175	1	1	f79098c11b55e9b6aef2a19967a56948	WITH seconds AS (\n  SELECT generate_series(\n    date_trunc('second', now() AT TIME ZONE 'UTC') - interval '360 seconds',\n    date_trunc('second', now() AT TIME ZONE 'UTC'),\n    interval '1 second'\n  ) AS second_ts\n)\nSELECT\n  s.second_ts AS measured_at,\n  ws.name     AS station,\n  AVG(m.temperature_c) AS temperature_c\nFROM seconds s\nCROSS JOIN weather_station ws\nLEFT JOIN weather_measurement m\n  ON m.station_id = ws.id\n AND date_trunc('second', m.measured_at AT TIME ZONE 'UTC') = s.second_ts\nGROUP BY s.second_ts, ws.name\nORDER BY s.second_ts, ws.name;	{"rows": [{"temperature_c": -0.38108393845364064, "station": "Station Center", "measured_at": "2025-12-27T12:50:09"}, {"temperature_c": 3.4446842141980807, "station": "Station East", "measured_at": "2025-12-27T12:50:09"}, {"temperature_c": -4.469756335644023, "station": "Station North", "measured_at": "2025-12-27T12:50:09"}, {"temperature_c": 4.652611414449197, "station": "Station South", "measured_at": "2025-12-27T12:50:09"}, {"temperature_c": 3.048600493941225, "station": "Station West", "measured_at": "2025-12-27T12:50:09"}, {"temperature_c": 1.33531890978053, "station": "Station Center", "measured_at": "2025-12-27T12:50:10"}, {"temperature_c": 3.458564627413635, "station": "Station East", "measured_at": "2025-12-27T12:50:10"}, {"temperature_c": -6.203494986190611, "station": "Station North", "measured_at": "2025-12-27T12:50:10"}, {"temperature_c": 6.499734805844911, "station": "Station South", "measured_at": "2025-12-27T12:50:10"}, {"temperature_c": 5.245499386916263, "station": "Station West", "measured_at": "2025-12-27T12:50:10"}, {"temperature_c": 1.6972328789352495, "station": "Station Center", "measured_at": "2025-12-27T12:50:11"}, {"temperature_c": 4.137039621172671, "station": "Station East", "measured_at": "2025-12-27T12:50:11"}, {"temperature_c": -7.9157460295538735, "station": "Station North", "measured_at": "2025-12-27T12:50:11"}, {"temperature_c":