181	1	1	1ec6bcfdac682a0640f9b426e1de58e0	WITH seconds AS (\n  SELECT generate_series(\n    date_trunc('second', now() AT TIME ZONE 'UTC') - interval '60 seconds',\n    date_trunc('second', now() AT TIME ZONE 'UTC'),\n    interval '1 second'\n  ) AS second_ts\n)\nSELECT\n  s.second_ts AS measured_at,\n  ws.name     AS station,\n  AVG(m.temperature_c) AS temperature_c\nFROM seconds s\nCROSS JOIN weather_station ws\nLEFT JOIN weather_measurement m\n  ON m.station_id = ws.id\n AND date_trunc('second', m.measured_at AT TIME ZONE 'UTC') = s.second_ts\nGROUP BY s.second_ts, ws.name\nORDER BY s.second_ts, ws.name;	{"rows": [{"temperature_c": null, "station": "Station Center", "measured_at": "2025-12-27T12:57:43"}, {"temperature_c": null, "station": "Station East", "measured_at": "2025-12-27T12:57:43"}, {"temperature_c": null, "station": "Station North", "measured_at": "2025-12-27T12:57:43"}, {"temperature_c": null, "station": "Station South", "measured_at": "2025-12-27T12:57:43"}, {"temperature_c": null, "station": "Station West", "measured_at": "2025-12-27T12:57:43"}, {"temperature_c": null, "station": "Station Center", "measured_at": "2025-12-27T12:57:44"}, {"temperature_c": null, "station": "Station East", "measured_at": "2025-12-27T12:57:44"}, {"temperature_c": null, "station": "Station North", "measured_at": "2025-12-27T12:57:44"}, {"temperature_c": null, "station": "Station South", "measured_at": "2025-12-27T12:57:44"}, {"temperature_c": null, "station": "Station West", "measured_at": "2025-12-27T12:57:44"}, {"temperature_c": null, "station": "Station Center", "measured_at": "2025-12-27T12:57:45"}, {"temperature_c": null, "station": "Station East", "measured_at": "2025-12-27T12:57:45"}, {"temperature_c": null, "station": "Station North", "measured_at": "2025-12-27T12:57:45"}, {"temperature_c": null, "station": "Station South", "measured_at": "2025-12-27T12:57:45"}, {"temperature_c": null, "station": "Station West", "measured_at": "2025-12-27T12:57:45"}, {"temperature_